import React from 'react';

import type { Pipeline, PipelineInstruction } from '../simulator/protocol';
import type { PipelineColors } from '../settings/schema';
import { DEFAULT_PIPELINE_COLORS } from '../settings/schema';

/*
 * Graphical Pipeline widget for the Web UI.
 *
 * The layout mirrors `org.edumips64.ui.swing.GUIPipeline`: IF and ID on the
 * left of the central pipeline axis, MEM and WB on the right, EX above the
 * axis, and the FPU functional units (Multiplier, Adder, Divider) stacked
 * around it. Active stages are filled with their per-stage color (which is
 * persisted and customizable from the Settings panel) and the running
 * instruction's name is rendered inside the block.
 *
 * Bubbles render as empty stages — the same way Swing's `GUIPipeline`
 * paints them. Only when an actual stall occurred in the current cycle
 * (detected via the `Stage` tag attached on the Java side by reusing the
 * Swing `CycleBuilder`) is a stage drawn with the dedicated `Stall` color
 * and a stall-type label (RAW / WAW / Struct: Div / Struct: EX / Struct:
 * FU / Struct: Mem / Struct: Add / Struct: Mul). Note that the simulator
 * does not produce WAR hazards (in-order issue + late writeback orders
 * reads before writes), so no WAR tag exists.
 */

// SVG canvas dimensions. The component is laid out in this coordinate space
// and then scaled to the available width via `viewBox` + `preserveAspectRatio`.
const VIEW_W = 600;
const VIEW_H = 320;

interface BoxGeometry {
  x: number;
  y: number;
  w: number;
  h: number;
}

// Geometry of the five integer stages. `x`/`y` is the top-left corner and
// `w`/`h` are the box dimensions, in viewBox units. The EX block mirrors the
// FP Divider block geometry (same width and horizontal position) so the
// integer-pipeline diagram is vertically symmetric: ID/MEM connect to EX
// with the same diagonal pattern they use for the FP Divider.
const STAGE_BOXES: Record<string, BoxGeometry> = {
  IF: { x: 20, y: 140, w: 60, h: 50 },
  ID: { x: 110, y: 140, w: 60, h: 50 },
  EX: { x: 205, y: 30, w: 190, h: 40 },
  MEM: { x: 430, y: 140, w: 60, h: 50 },
  WB: { x: 520, y: 140, w: 60, h: 50 },
};

// FPU functional units, computed below. The Multipliers row sits above the
// integer axis and the Adders row sits below it, with the Divider at the
// bottom — same topology as the Swing widget.
const FPU_LEFT = 195;
const FPU_RIGHT = 405;
const FPU_WIDTH = FPU_RIGHT - FPU_LEFT;

const FP_MULT_COUNT = 7;
const FP_MULT_Y = 95;
const FP_MULT_H = 30;
const FP_MULT_GAP = 4;
const FP_MULT_W =
  (FPU_WIDTH - FP_MULT_GAP * (FP_MULT_COUNT - 1)) / FP_MULT_COUNT;

const FP_ADD_COUNT = 4;
const FP_ADD_Y = 205;
const FP_ADD_H = 30;
const FP_ADD_GAP = 6;
const FP_ADD_W = (FPU_WIDTH - FP_ADD_GAP * (FP_ADD_COUNT - 1)) / FP_ADD_COUNT;

const FP_DIV_BOX: BoxGeometry = { x: 205, y: 260, w: 190, h: 40 };

const fpMultBox = (i: number): BoxGeometry => ({
  x: FPU_LEFT + i * (FP_MULT_W + FP_MULT_GAP),
  y: FP_MULT_Y,
  w: FP_MULT_W,
  h: FP_MULT_H,
});
const fpAddBox = (i: number): BoxGeometry => ({
  x: FPU_LEFT + i * (FP_ADD_W + FP_ADD_GAP),
  y: FP_ADD_Y,
  w: FP_ADD_W,
  h: FP_ADD_H,
});

// Bubbles use the empty placeholder name " " or are altogether `null`.
// Either way, they render as empty stage outlines (matching `GUIPipeline`).
const isOccupied = (
  instr: PipelineInstruction | null,
): instr is PipelineInstruction =>
  !!instr && !!instr.Name && instr.Name !== ' ';

// Stage-tag set produced by `CycleBuilder` when an instruction was *stalled*
// in the most recent CPU cycle. Each tag maps to a short user-friendly
// label rendered inside the stage block. The two-character `Dxx` divider
// counter states (`DIV_COUNT` + numeric `DivCount`) and the integer/normal
// stage tags (`IF`, `ID`, `EX`, `MEM`, `WB`, `A1`..`A4`, `M1`..`M7`, `DIV`)
// are *not* stalls and intentionally absent here.
const STALL_LABELS: Record<string, string> = {
  RAW: 'RAW',
  WAW: 'WAW',
  StDiv: 'Struct: Div',
  StEx: 'Struct: EX',
  StFun: 'Struct: FU',
  Str: 'Struct: Mem',
  StAdd: 'Struct: Add',
  StMul: 'Struct: Mul',
};

// `instr.Stage` is sourced from a Java `@JsType` enum (`CycleState`) on the
// worker side. Across the worker `postMessage` boundary the enum may surface
// as either a plain string (its `name()`) or as an object that string-coerces
// to its name; coerce defensively here so the lookup works either way and
// `null`/`undefined` (no stage info yet) cleanly returns no label.
const stageName = (stage: string | null | unknown): string | null =>
  stage == null ? null : typeof stage === 'string' ? stage : String(stage);

const stallLabel = (instr: PipelineInstruction): string | null => {
  const name = stageName(instr?.Stage);
  return (name && STALL_LABELS[name]) || null;
};

interface StageBoxProps {
  box: BoxGeometry;
  label: string;
  instr: PipelineInstruction | null;
  fillColor: string;
  stallColor: string;
  outlineColor: string;
  textColor: string;
}

/**
 * Render a single rectangular pipeline stage.
 *
 * Three visual states:
 *   - empty (bubble or no instruction): outline only.
 *   - active: filled with `fillColor`, instruction mnemonic centered.
 *   - stalled: filled with `stallColor`, hatched, instruction mnemonic on
 *     top and a small stall-type tag below.
 */
const StageBox = ({
  box,
  label,
  instr,
  fillColor,
  stallColor,
  outlineColor,
  textColor,
}: StageBoxProps) => {
  const occupied = isOccupied(instr);
  const stall = occupied ? stallLabel(instr) : null;
  // The CycleBuilder's per-instruction stage tag (e.g. "IF"/"ID"/"EX"/.../
  // "RAW"/"WAW"/"StDiv"/...) for the most recently completed cycle. Used by
  // tests to verify `CycleBuilder` advances even when `cpu.step()` throws
  // (`BreakException`, `InputNeededException`, `SynchronousException`); see
  // `src/main/java/org/edumips64/client/Simulator.java`.
  const cycleStage = occupied ? stageName(instr.Stage) || '' : '';
  const fill = stall ? stallColor : occupied ? fillColor : 'white';
  const cx = box.x + box.w / 2;
  // Vertical layout depends on whether we render only the stage label, the
  // stage label + instruction name, or label + name + stall tag.
  const stageLabelY = occupied ? box.y + box.h * 0.32 : box.y + box.h / 2 + 4;
  const instrNameY = stall ? box.y + box.h * 0.6 : box.y + box.h * 0.78;
  const stallTagY = box.y + box.h * 0.85;
  // Expose the per-stage state via `data-*` attributes so the Playwright
  // tests can read pipeline contents and stall classifications without
  // having to parse rendered SVG text.
  return (
    <g
      data-stage={label}
      data-instruction={occupied ? instr.Name : ''}
      data-stall={stall || ''}
      data-cycle-stage={cycleStage}
      data-fill={fill}
    >
      <rect
        x={box.x}
        y={box.y}
        width={box.w}
        height={box.h}
        fill={fill}
        stroke={outlineColor}
        strokeWidth={1.2}
      />
      {stall && (
        // Diagonal hatching makes stalls visually distinct from active
        // stages even when the user picks a stall color close to a stage
        // color.
        <rect
          x={box.x}
          y={box.y}
          width={box.w}
          height={box.h}
          fill="url(#pipelineStallHatch)"
          pointerEvents="none"
        />
      )}
      <text
        x={cx}
        y={stageLabelY}
        textAnchor="middle"
        fontSize="12"
        fontWeight="bold"
        fill={textColor}
      >
        {label}
      </text>
      {occupied && (
        <text
          x={cx}
          y={instrNameY}
          textAnchor="middle"
          fontSize="11"
          fill={textColor}
        >
          {instr.Name}
        </text>
      )}
      {stall && (
        <text
          x={cx}
          y={stallTagY}
          textAnchor="middle"
          fontSize="9"
          fontStyle="italic"
          fill={textColor}
        >
          {stall}
        </text>
      )}
    </g>
  );
};

interface WireProps {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  color: string;
}

/**
 * Render a thin connector line between two stages. The lines mirror the
 * arrows drawn by the Swing widget but are kept un-arrowheaded for clarity
 * at small sizes.
 */
const Wire = ({ x1, y1, x2, y2, color }: WireProps) => (
  <line
    x1={x1}
    y1={y1}
    x2={x2}
    y2={y2}
    stroke={color}
    strokeWidth={1}
    strokeLinecap="round"
  />
);

/**
 * Render a thin connector line between two stages — see {@link Wire}. The
 * pipeline diagram is now drawn entirely with straight diagonal/horizontal
 * `Wire`s, so no polyline helper is needed.
 */

interface PipelineProps {
  pipeline: Pipeline;
  colors?: PipelineColors | undefined;
}

const PipelineWidget = ({ pipeline, colors }: PipelineProps) => {
  // `colors` is the persisted setting; fall back to the schema defaults so
  // the widget keeps working even if it is rendered before settings are
  // wired in (e.g. in unit tests).
  const c = { ...DEFAULT_PIPELINE_COLORS, ...(colors || {}) };
  const outline = '#444';
  const text = '#111';

  const fpMult = [
    pipeline.FPMultiplier1,
    pipeline.FPMultiplier2,
    pipeline.FPMultiplier3,
    pipeline.FPMultiplier4,
    pipeline.FPMultiplier5,
    pipeline.FPMultiplier6,
    pipeline.FPMultiplier7,
  ];
  const fpAdd = [
    pipeline.FPAdder1,
    pipeline.FPAdder2,
    pipeline.FPAdder3,
    pipeline.FPAdder4,
  ];
  const fpDiv = pipeline.FPDivider;

  // Section labels.
  const fpuLabelXMult = (FPU_LEFT + FPU_RIGHT) / 2;
  const fpuLabelXAdd = (FPU_LEFT + FPU_RIGHT) / 2;

  return (
    <div id="pipeline" data-testid="pipeline-widget">
      <svg
        viewBox={`0 0 ${VIEW_W} ${VIEW_H}`}
        preserveAspectRatio="xMidYMid meet"
        style={{ width: '100%', height: 'auto', maxHeight: 360 }}
        role="img"
        aria-label="Pipeline diagram"
      >
        <defs>
          <pattern
            id="pipelineStallHatch"
            patternUnits="userSpaceOnUse"
            width="6"
            height="6"
            patternTransform="rotate(45)"
          >
            <line
              x1="0"
              y1="0"
              x2="0"
              y2="6"
              stroke="rgba(0,0,0,0.35)"
              strokeWidth="2"
            />
          </pattern>
        </defs>

        {/* Connectors (drawn first so the boxes paint on top) */}
        {/* IF -> ID */}
        <Wire x1={80} y1={165} x2={110} y2={165} color={outline} />
        {/* ID -> EX: diagonal from the top edge of ID up to the left edge
            of EX. Mirrors the ID -> FP Divider connector below for vertical
            symmetry. */}
        <Wire
          x1={170}
          y1={145}
          x2={STAGE_BOXES.EX.x}
          y2={STAGE_BOXES.EX.y + STAGE_BOXES.EX.h / 2}
          color={outline}
        />
        {/* EX -> MEM: symmetric diagonal from the right edge of EX down to
            the top edge of MEM. */}
        <Wire
          x1={STAGE_BOXES.EX.x + STAGE_BOXES.EX.w}
          y1={STAGE_BOXES.EX.y + STAGE_BOXES.EX.h / 2}
          x2={430}
          y2={145}
          color={outline}
        />
        {/* MEM -> WB */}
        <Wire x1={490} y1={165} x2={520} y2={165} color={outline} />

        {/* ID -> FP Multiplier1, FP Mult7 -> MEM */}
        <Wire
          x1={170}
          y1={158}
          x2={fpMultBox(0).x}
          y2={FP_MULT_Y + FP_MULT_H / 2}
          color={outline}
        />
        <Wire
          x1={fpMultBox(FP_MULT_COUNT - 1).x + FP_MULT_W}
          y1={FP_MULT_Y + FP_MULT_H / 2}
          x2={430}
          y2={158}
          color={outline}
        />
        {/* FP Mult inter-stage wires */}
        {Array.from({ length: FP_MULT_COUNT - 1 }).map((_, i) => {
          const a = fpMultBox(i);
          const b = fpMultBox(i + 1);
          return (
            <Wire
              key={`mw-${i}`}
              x1={a.x + a.w}
              y1={a.y + a.h / 2}
              x2={b.x}
              y2={b.y + b.h / 2}
              color={outline}
            />
          );
        })}

        {/* ID -> FP Adder1, FP Add4 -> MEM */}
        <Wire
          x1={170}
          y1={172}
          x2={fpAddBox(0).x}
          y2={FP_ADD_Y + FP_ADD_H / 2}
          color={outline}
        />
        <Wire
          x1={fpAddBox(FP_ADD_COUNT - 1).x + FP_ADD_W}
          y1={FP_ADD_Y + FP_ADD_H / 2}
          x2={430}
          y2={172}
          color={outline}
        />
        {Array.from({ length: FP_ADD_COUNT - 1 }).map((_, i) => {
          const a = fpAddBox(i);
          const b = fpAddBox(i + 1);
          return (
            <Wire
              key={`aw-${i}`}
              x1={a.x + a.w}
              y1={a.y + a.h / 2}
              x2={b.x}
              y2={b.y + b.h / 2}
              color={outline}
            />
          );
        })}

        {/* ID -> FP Divider, FP Divider -> MEM */}
        <Wire
          x1={170}
          y1={185}
          x2={FP_DIV_BOX.x}
          y2={FP_DIV_BOX.y + FP_DIV_BOX.h / 2}
          color={outline}
        />
        <Wire
          x1={FP_DIV_BOX.x + FP_DIV_BOX.w}
          y1={FP_DIV_BOX.y + FP_DIV_BOX.h / 2}
          x2={430}
          y2={185}
          color={outline}
        />

        {/* Section labels */}
        <text
          x={fpuLabelXMult}
          y={FP_MULT_Y - 5}
          textAnchor="middle"
          fontSize="11"
          fontStyle="italic"
          fill={text}
        >
          FP Multiplier
        </text>
        <text
          x={fpuLabelXAdd}
          y={FP_ADD_Y - 5}
          textAnchor="middle"
          fontSize="11"
          fontStyle="italic"
          fill={text}
        >
          FP Adder
        </text>

        {/* Integer stages */}
        <StageBox
          box={STAGE_BOXES.IF}
          label="IF"
          instr={pipeline.IF}
          fillColor={c.IF}
          stallColor={c.Stall}
          outlineColor={outline}
          textColor={text}
        />
        <StageBox
          box={STAGE_BOXES.ID}
          label="ID"
          instr={pipeline.ID}
          fillColor={c.ID}
          stallColor={c.Stall}
          outlineColor={outline}
          textColor={text}
        />
        <StageBox
          box={STAGE_BOXES.EX}
          label="EX"
          instr={pipeline.EX}
          fillColor={c.EX}
          stallColor={c.Stall}
          outlineColor={outline}
          textColor={text}
        />
        <StageBox
          box={STAGE_BOXES.MEM}
          label="MEM"
          instr={pipeline.MEM}
          fillColor={c.MEM}
          stallColor={c.Stall}
          outlineColor={outline}
          textColor={text}
        />
        <StageBox
          box={STAGE_BOXES.WB}
          label="WB"
          instr={pipeline.WB}
          fillColor={c.WB}
          stallColor={c.Stall}
          outlineColor={outline}
          textColor={text}
        />

        {/* FPU Multipliers */}
        {fpMult.map((instr, i) => (
          <StageBox
            key={`mul-${i}`}
            box={fpMultBox(i)}
            label={`M${i + 1}`}
            instr={instr}
            fillColor={c.FPMultiplier}
            stallColor={c.Stall}
            outlineColor={outline}
            textColor={text}
          />
        ))}

        {/* FPU Adders */}
        {fpAdd.map((instr, i) => (
          <StageBox
            key={`add-${i}`}
            box={fpAddBox(i)}
            label={`A${i + 1}`}
            instr={instr}
            fillColor={c.FPAdder}
            stallColor={c.Stall}
            outlineColor={outline}
            textColor={text}
          />
        ))}

        {/* FPU Divider */}
        <StageBox
          box={FP_DIV_BOX}
          label="FP Divider"
          instr={fpDiv}
          fillColor={c.FPDivider}
          stallColor={c.Stall}
          outlineColor={outline}
          textColor={text}
        />
      </svg>
    </div>
  );
};

export default React.memo(PipelineWidget);
